[归一化后的问题]
SPU 数是多少？

[已审查的查询计划]
{
  "assets": [
    {
      "asset": "product",
      "join_key": null
    }
  ],
  "blocking_issues": [],
  "dimensions": [],
  "filters": [
    "on_sale = true（spu_cnt 默认在售口径，过滤条件写在指标表达式内）"
  ],
  "grain": "全量汇总（无分组）",
  "limit": 1,
  "metrics": [
    {
      "caliber": "按 product.spu_id 去重的存量计数（款数），默认在售口径：COUNT(DISTINCT product.spu_id) WHERE on_sale = true；time_basis=current，与时间区间无关",
      "name": "spu_cnt"
    }
  ],
  "order_by": [],
  "output_columns": [
    "spu_cnt"
  ],
  "time_range": {
    "end": null,
    "start": null
  }
}

