[归一化后的问题]
2026-08 的收货省份覆盖数是多少？

[已审查的查询计划]
{
  "assets": [
    {
      "asset": "order_paid",
      "join_key": null
    }
  ],
  "blocking_issues": [],
  "dimensions": [],
  "filters": [
    "order_paid.pay_time 落在 2026-08-01 至 2026-08-31（含边界）",
    "order_paid.region_code IS NOT NULL（写在指标表达式内）",
    "默认谓词：pay_status = 'paid'；refund_status <> 'refunded'；is_test_order = false"
  ],
  "grain": "汇总（无分组，单行结果）",
  "limit": 100,
  "metrics": [
    {
      "caliber": "收货省份覆盖数 province_covered_cnt：COUNT(DISTINCT order_paid.region_code) WHERE region_code IS NOT NULL；按支付完成时间 pay_time 统计，跨列去重，落在事实表；仅统计已支付、未全额退款、非测试单",
      "name": "province_covered_cnt"
    }
  ],
  "order_by": [],
  "output_columns": [
    "province_covered_cnt"
  ],
  "time_range": {
    "end": "2026-08-31",
    "start": "2026-08-01"
  }
}

